var req = new HttpRequest();
req.addHeader('Content-Type: application/json');
req.post('{$STORWARE.API.URL}/session/login', JSON.stringify({login: '{$STORWARE.USER}', password: '{$STORWARE.PASSWORD}'}));
var response = req.get('{$STORWARE.API.URL}/backups');
var backups = JSON.parse(response);
var now = Date.now();
var threshold = {$STORWARE.BACKUP.CHECK.HOURS} * 60 * 60 * 1000;
var count = 0;
for (var i = 0; i < backups.length; i++) {
    var b = backups[i];
    if (b.status && b.status.name === 'FAILED') {
        var backupTime = b.snapshotTime || b.backupTime || 0;
        if ((now - backupTime) <= threshold) count++;
    }
}
return count;

var req = new HttpRequest();
req.addHeader('Content-Type: application/json');
req.post('{$STORWARE.API.URL}/session/login', JSON.stringify({login: '{$STORWARE.USER}', password: '{$STORWARE.PASSWORD}'}));
var response = req.get('{$STORWARE.API.URL}/backups');
var backups = JSON.parse(response);
var now = Date.now();
var threshold = {$STORWARE.BACKUP.CHECK.HOURS} * 60 * 60 * 1000;
var failed = [];
for (var i = 0; i < backups.length; i++) {
    var b = backups[i];
    if (b.status && b.status.name === 'FAILED') {
        var backupTime = b.snapshotTime || b.backupTime || 0;
        if ((now - backupTime) <= threshold) {
            var name = b.protectedEntity ? b.protectedEntity.name : 'Unknown';
            if (failed.indexOf(name) === -1) failed.push(name);
        }
    }
}
return failed.length > 0 ? failed.join(', ') : 'No failed backups';

