var req = new HttpRequest();
req.addHeader('Content-Type: application/json');
req.post('{$STORWARE.API.URL}/session/login', JSON.stringify({login: '{$STORWARE.USER}', password: '{$STORWARE.PASSWORD}'}));
var response = req.get('{$STORWARE.API.URL}/backup-destinations');
var bds = JSON.parse(response);
var used = 0, total = 0;
for (var i = 0; i < bds.length; i++) {
    used += bds[i].totalUsedSpace || 0;
    total += bds[i].totalSpace || 0;
}
if (total === 0) return 0;
return Math.round((used / total) * 10000) / 100;

