var now = Date.now();
var threshold = {$STORWARE.BACKUP.STALE.HOURS} * 60 * 60 * 1000;
var count = 0;
for (var i = 0; i < vms.length; i++) {
    if (vms[i].vmBackupPolicy && (!vms[i].lastBackup || (now - vms[i].lastBackup) > threshold)) count++;
}
return count;

